package com.aicharacter.v3;
/** Active autonomy evaluates at meaningful intervals, then executes a persistent plan instead of rerolling every frame. */
public final class HaruAutonomyEngine {private static final long DECISION_INTERVAL_MS=12000L;private HaruAutonomyEngine(){}
 public static void tick(WorldState s,float dt){if(s==null)return;BodyRhythmEngine.advanceSeconds(s,dt);if(s.environment!=null)s.environment.updateForTime(s.worldMinutes);if(s.emotion!=null)s.emotion.decay(Math.pow(.997,dt));if(s.mood!=null)s.mood.decay(Math.pow(.9997,dt));long now=System.currentTimeMillis();if(BodyRhythmEngine.shouldRemainAsleep(s))return;if(BodyRhythmEngine.isSleeping(s))s.haruActivity="waking slowly";if(s.planState==null)s.planState=new PlanState();if(s.girlTravel!=null&&s.girlTravel.active){long travelAnchor=s.planState.lastReconsideredAt;if(travelAnchor<=0||now-travelAnchor>=DECISION_INTERVAL_MS){PlanIntegrityChecker.check(s,now);PlanReconsiderationEngine.Result travelDecision=PlanReconsiderationEngine.evaluate(s,now);s.planState.lastReconsideredAt=now;if(travelDecision.reconsider())PlanExecutor.applyDecision(s,travelDecision,now);}return;}long anchor=s.planState.lastReconsideredAt;if(anchor>0&&now-anchor<DECISION_INTERVAL_MS)return;if("PAUSED".equals(s.planState.status)){s.planState.lastReconsideredAt=now;if(PlanExecutor.resume(s,now))return;}if(("COMPLETED".equals(s.planState.status)||"FAILED".equals(s.planState.status)||"ABANDONED".equals(s.planState.status))&&s.planState.lastProgressAt>0&&now-s.planState.lastProgressAt<DECISION_INTERVAL_MS)return;PlanIntegrityChecker.check(s,now);PlanReconsiderationEngine.Result rr=PlanReconsiderationEngine.evaluate(s,now);s.planState.lastReconsideredAt=now;if(s.planState.active()&&!rr.reconsider())return;if(rr.reconsider()){PlanExecutor.applyDecision(s,rr,now);if(s.planState.active())return;}LifeDecision d=LifeDecisionEngine.choose(s,now);OfflineLifeEngine.beginDecision(s,d,now);if(s.mood!=null)s.haruMood=s.mood.label();}
}
